#include <stdio.h>
int main(void) {
 double a, b;
 char op;
 if (scanf("%lf %c %lf", &a, &op, &b) != 3) return 1;
 if (op == '/' && b == 0.0) { puts("division by zero"); return 1; }
 switch (op) {
 case '+': printf("%.2f\n", a+b); break;
 case '-': printf("%.2f\n", a-b); break;
 case '*': printf("%.2f\n", a*b); break;
 case '/': printf("%.2f\n", a/b); break;
 default: puts("unknown operator"); return 1;
 }
 return 0;
}
